    def test_result_is_valid_remediation_level(self):
        """Verify result is always a valid remediation level."""
        valid_levels = {level.value for level in _RemediationLevel}
        test_cases = [
            {},
            {"cpu_load": 50.0},
            {"cpu_load": 85.0},
            {"cpu_load": 95.0, "memory_usage": 90.0},
            {"cpu_load": 99.0, "memory_usage": 98.0, "disk_space": 99.0},
        ]
        for metrics in test_cases:
            result = CoherenceThresholds.check_stability(metrics)
            assert result in valid_levels, f"Invalid level {result} for {metrics}"

    def test_monotonic_severity(self):
        """Verify severity increases monotonically with metric values."""
        for metric_key in ["cpu_load", "memory_usage", "disk_space"]:
            previous_level = _RemediationLevel.STABLE
            for value in [50.0, 82.0, 92.0, 97.0, 99.5]:
                metrics = {metric_key: value}
                result = CoherenceThresholds.check_stability(metrics)
                current_level = _RemediationLevel(result)
                # Current level should be >= previous level
                assert list(_RemediationLevel).index(current_level) >= list(_RemediationLevel).index(previous_level), \
                    f"Severity decreased for {metric_key}={value}"
                previous_level = current_level

    def test_idempotent_with_same_metrics(self):
        """Verify same metrics always produce same result."""
        metrics = {"cpu_load": 85.0, "memory_usage": 90.0}
        result1 = CoherenceThresholds.check_stability(metrics)
        result2 = CoherenceThresholds.check_stability(metrics)
        result3 = CoherenceThresholds.check_stability(metrics)
        assert result1 == result2 == result3


